// docs/TERMS.md is generated by `pnpm terms:doc`; this holds the committed file to the
// generator, so the worked table is always what terms() computes.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { renderTermsDoc, renderWorkedTable } from "../../packages/vendor/src/index.js";
import { describe, expect, it } from "vitest";

const ROOT = resolve(import.meta.dirname, "../..");

describe("docs/TERMS.md", () => {
  it("is the generator's output for its own date, and the worked table is terms() run", () => {
    const text = readFileSync(resolve(ROOT, "docs/TERMS.md"), "utf8");
    const date = /generated by `pnpm terms:doc` from `packages\/vendor\/src\/terms\/doc.ts` on (\d{4}-\d{2}-\d{2});/.exec(text)?.[1];
    expect(date).toBeDefined();
    expect(text).toBe(renderTermsDoc({ generatedOn: date! }));
    expect(text).toContain(renderWorkedTable());
    // The briefing's three worked numbers at 0.01 USDC.
    expect(text).toContain("| unknown buyer (or a rotated address) | 0 | 0 | 0.010000 | 20 | 0.200000 |");
    expect(text).toContain("| seven clean periods | 1750 | 0 | 0.008250 | 6 | 0.049500 |");
    expect(text).toContain("| one `close_with_unpaid` | 0 | 2000 | 0.012000 | 50 | 0.600000 |");
  });
});
